import re
lines = open("governance/check-registry.yaml", encoding="utf-8").read().split("\n")
# find check id blocks: lines starting with "- id:" at 2-space indent
id_lines = [(i, l) for i,l in enumerate(lines) if re.match(r'^\s*- id:\s*', l)]
def nearest_id(lineno):
    prev = None
    for i, l in id_lines:
        if i <= lineno:
            prev = l.strip()
        else:
            break
    return prev

pattern = re.compile(r'(\d[\d,]*)\s+today')
for i, l in enumerate(lines):
    for m in pattern.finditer(l):
        print(i+1, nearest_id(i), "->", m.group(0), "|", l.strip()[:140])
